package org.apache.commons.math3.optimization.direct;

import org.apache.commons.math3.analysis.MultivariateFunction;
import org.apache.commons.math3.optimization.GoalType;
import org.apache.commons.math3.optimization.PointValuePair;
import org.apache.commons.math3.random.MersenneTwister;
import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_20_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Define a simple quadratic function
        MultivariateFunction quadraticFunction = new MultivariateFunction() {
            @Override
            public double value(double[] point) {
                double sum = 0;
                for (double x : point) {
                    sum += x * x;
                }
                return sum;
            }
        };

        // Set up the optimizer with bounds
        CMAESOptimizer optimizer = new CMAESOptimizer(10, new double[]{0.3, 0.3}, 1000, 0,
                true, 0, 0, new MersenneTwister(), false) {
            @Override
            public double[] getLowerBound() {
                return new double[]{0.0, 0.0};
            }

            @Override
            public double[] getUpperBound() {
                return new double[]{1.0, 1.0};
            }
        };

        // Perform optimization
        PointValuePair result = optimizer.optimize(1000, quadraticFunction, GoalType.MINIMIZE, new double[]{1.5, -0.5});

        // Check if the result is within the expected boundaries
        double[] point = result.getPoint();
        for (double x : point) {
            assertTrue("The optimization result is out of bounds.", x >= 0.0 && x <= 1.0);
        }
    }
}

