package org.apache.commons.math3.optimization.direct;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_20_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        CMAESOptimizer.FitnessFunction fitnessFunction = new CMAESOptimizer().new FitnessFunction();

        // Set up boundaries and repair mode
        fitnessFunction.boundaries = new double[][]{{0.0, 0.0}, {1.0, 1.0}};
        fitnessFunction.isRepairMode = true;

        // Input that requires repair
        double[] input = {1.5, -0.5};

        // Expected output after repair and decode
        double[] expectedOutput = {1.0, 0.0};

        // Call repairAndDecode and check the result
        double[] result = fitnessFunction.repairAndDecode(input);

        // Assert that the result is as expected
        assertArrayEquals("The repairAndDecode method did not repair the input as expected.", expectedOutput, result, 1e-9);
    }
}

